return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-06 01:48+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=3; plural=(n==1 ? 0 : (n==0 || (n%100 > 0 && n%100 < 20)) ? 1 : 2);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Mergeți la Căutare plugin','Activate %s' => 'Activați %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> necesită <strong>%2$s</strong> pentru a fi instalat și activat. <a href="%4$s">%3$s</a>','Enter your code here' => 'Introduceți codul dvs. aici','Add %s' => 'Adăugați %s','Remove' => 'Eliminați','Order number and receipt will be sent to this email address.' => 'Numărul comenzii și chitanța vor fi trimise la această adresă de e-mail.','Apartment, unit, building, floor, etc.' => 'Apartament, unitate, clădire, etaj, etc.','Shipping phone' => 'Telefon de expediere','Only used for shipping-related questions.' => 'Utilizat numai pentru întrebări legate de expediere.','Single step' => 'Un singur pas','Click to go to the order summary' => 'Faceți clic pentru a merge la rezumatul comenzii','Cart total:' => 'Total coș:','Proceed to %s' => 'Continuați la %s','Proceed to contact' => 'Procedați la contact','Proceed to shipping' => 'Procedați la expediere','Proceed to billing' => 'Treceți la facturare','Proceed to payment' => 'Procedați la plată','Shipping method' => 'Metoda de expediere','Additional notes' => 'Note suplimentare','Payment method' => 'Metoda de plată','Step %1$s of %2$s' => 'Pasul %1$s din %2$s','Change: %s' => 'Modificare: %s','Not selected yet.' => 'Nu a fost selectat încă.','Same as shipping address' => 'Aceeași ca adresa de expediere','Same as billing address' => 'Aceeași ca adresa de facturare','Order summary' => 'Rezumatul comenzii','Edit cart' => 'Editare coș','Did you mean %s?' => 'Ați vrut să spuneți %s?','Change email address to: {suggestion-value}' => 'Schimbați adresa de e-mail la: {sugestie-valoare}','This is a required field.' => 'Acesta este un câmp obligatoriu.','This is not a valid email address.' => 'Aceasta nu este o adresă de e-mail validă.','This field does not match the related field value.' => 'Acest câmp nu corespunde valorii câmpului aferent.','The CPF number "{cpf_number}" is invalid.' => 'Numărul CPF "{cpf_number}" este invalid.','The CNPJ number "{cnpj_number}" is invalid.' => 'Numărul CNPJ "{cnpj_number}" este invalid.','(Required)' => '(obligatoriu)','Checkout Header - Desktop' => 'Antet de plată - Desktop','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Afișează widget-uri pe antetul de plată pentru ecrane mari. Afișat numai dacă utilizați antetul de plată al pluginului.','Checkout Header - Mobile' => 'Antet de plată - mobil','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Afișează widget-uri sub antetul de plată pentru dispozitive mobile. Afișat numai dacă se utilizează antetul de checkout al pluginului.','Checkout Sidebar' => 'Checkout Sidebar','Display widgets on the checkout sidebar after the order summary.' => 'Afișați widget-uri în bara laterală a comenzii după rezumatul comenzii.','Checkout Order Summary' => 'Checkout Rezumatul comenzii','Display widgets inside the order summary at the checkout page.' => 'Afișați widget-uri în cadrul sumarului comenzii la pagina de plată.','Checkout Below Place Order' => 'Checkout Mai jos Plasați comanda','Display widgets below the place order button at the checkout page.' => 'Afișați widget-uri sub butonul de plasare a comenzii la pagina de plată.','Checkout Footer' => 'Picior de subsol Checkout','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Afișează widget-uri în subsolul paginii de checkout. Afișat numai dacă utilizați subsolul de plată al pluginului.','Classic' => 'Clasic','Boxed' => 'Cutie','Split' => 'Despărțit','Minimalist' => 'Minimalist','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Plugin-uri Fluid Checkout și Delivery Date de CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Am detectat că utilizați pluginurile Delivery & Pickup Date Time pentru WooCommerce (gratuit și PRO) de la CodeRockz. Integrarea cu aceste pluginuri a fost mutată la Fluid Checkout PRO.</p>','Upgrade to PRO' => 'Upgrade la PRO','Fluid Checkout database updated successfully' => 'Baza de date Fluid Checkout a fost actualizată cu succes','The database changes where applied successfully.' => 'Modificările aduse bazei de date au fost aplicate cu succes.','Dismiss' => 'Respinge','Fluid Checkout database update' => 'Actualizarea bazei de date Fluid Checkout','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Sunt necesare unele modificări ale bazei de date. Ca în cazul oricărei actualizări, vă recomandăm să <strong>faceți o copie de rezervă completă a site-ului dvs. înainte de a continua</strong>.','Update database' => 'Actualizarea bazei de date','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout nu este compatibil cu aspectul de checkout Divi Builder','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout are nevoie de formularul clasic de checkout WooCommerce bazat pe coduri scurte pentru a funcționa. Atunci când utilizați Divi Builder pentru a personaliza aspectul paginii de checkout, codurile scurte clasice sunt înlocuite cu widgeturi personalizate din Divi Builder pentru fiecare parte a paginii de checkout. Aceste widgeturi personalizate nu sunt compatibile cu Fluid Checkout.</p><p>Vă rugăm să editați pagina de checkout înlocuind widgeturile Divi Builder cu un widget text care conține codul scurt <code>[woocommerce_checkout]</code>.</p>','Edit the checkout page' => 'Editarea paginii de checkout','Read the documentation.' => 'Citiți documentația.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Funcția de checkout în mai mulți pași Germanized PRO trebuie să fie dezactivată atunci când se utilizează Fluid Checkout','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Atunci când utilizați Fluid Checkout, funcția în mai mulți pași din pluginul Germanized PRO devine inutilă și poate cauza <strong>erori critice în timpul procesării comenzilor noi</strong>. Vă rugăm să dezactivați funcția de checkout în mai mulți pași Germanized PRO în setările pluginului.','Go to Germanized settings' => 'Du-te la setările germanizate','Thanks for choosing Fluid Checkout!' => 'Vă mulțumim pentru că ați ales Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Folosiți pluginul de ceva timp. Cum vă place până acum? <br>Vă rugăm să ne dați un rating rapid, apreciem fiecare feedback și ne încurajează să continuăm să îmbunătățim plugin-ul :)','Rate the plugin' => 'Evaluați pluginul','I need help!' => 'Am nevoie de ajutor!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Este posibil ca unele caracteristici ale WooCommerce Checkout Manager by Quadlayers să nu funcționeze conform așteptărilor atunci când îl utilizați cu Fluid Checkout. Citiți <a href="%s">documentația noastră</a> pentru mai multe informații și soluții alternative.','Read documentation' => 'Citește documentația','Don\'t show this again' => 'Nu arătați asta din nou','Fluid Checkout PRO' => 'Verificarea fluidelor PRO','More design templates' => 'Mai multe modele de design','Optimized cart page' => 'Pagina de coș optimizată','Optimized order received / thank you page' => 'Pagina optimizată de primire a comenzii / de mulțumire','Edit cart contents at checkout page' => 'Editarea conținutului coșului la pagina de plată','Account matching / user matching' => 'Potrivirea contului / potrivirea utilizatorului','Trust symbols on the cart and thank you pages' => 'Simboluri de încredere pe paginile de coș și de mulțumire','More positions for the coupon code on the checkout page' => 'Mai multe poziții pentru codul cuponului pe pagina de checkout','International phone numbers' => 'Numere de telefon internaționale','Gift messages and packing slips' => 'Mesaje cadou și fișe de ambalare','Local pickup and in-store collection' => 'Ridicare locală și colectare în magazin','EU-VAT Assistant' => 'Asistent EU-VAT','I already have it – Hide this offer' => 'Îl am deja - Ascundeți această ofertă','Activated' => 'Activat','Address book' => 'Carnet de adrese','Select an image' => 'Selectați o imagine','Cart layout' => 'Dispunerea coșului','Cart optimizations' => 'Optimizări coș','Enable cart page optimizations' => 'Activați optimizările paginii coșului','Header and footer template' => 'Șablon pentru antet și subsol','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Controlează dacă să se utilizeze antetul și subsolul paginii care nu distrage atenția sau să se păstreze antetul și subsolul temei active în prezent.','Distraction free header and footer' => 'Antet și subsol fără distragere a atenției','Theme\'s header and footer' => 'Antetul și subsolul temei','Cart elements' => 'Elemente ale coșului','Make the order summary stay visible on the cart page while scrolling' => 'Faceți ca rezumatul comenzii să rămână vizibil pe pagina coșului în timpul derulării','Coupon codes' => 'Coduri de cupon','Hidden' => 'Ascunse','Before the cart items section' => 'Înainte de secțiunea articole din coș','Inside the cart items section' => 'În secțiunea Articole din coș','After the cart items section' => 'După secțiunea articole din coș','Before the shipping section' => 'Înainte de secțiunea de expediere','After the shipping section' => 'După secțiunea de expediere','Before the order summary' => 'Înainte de rezumatul comenzii','Inside the order summary' => 'În rezumatul comenzii','Before the order totals' => 'Înainte de totalul comenzii','After the order totals' => 'După totalul comenzilor','After the order summary' => 'După rezumatul comenzii','Shipping' => 'Transport maritim','Select position where to display the shipping costs and calculator on the cart page.' => 'Selectați poziția în care să afișați costurile de expediere și calculatorul pe pagina coșului.','Display as a cart section' => 'Afișare ca secțiune a coșului','Cross-sells' => 'Vânzări încrucișate','Select position where to display the cross-sells section on the cart page.' => 'Selectați poziția în care să afișați secțiunea de vânzări încrucișate pe pagina coșului.','Before the cart actions' => 'Înainte de acțiunile din coș','After the cart actions' => 'După acțiunile din coș','Layout of cross-sell items on the cart page.' => 'Dispunerea elementelor de vânzare încrucișată pe pagina coșului.','Optimized horizontal cross-sells layout' => 'Layout orizontal optimizat pentru vânzări încrucișate','Theme\'s cross-sells layout' => 'Aspectul vânzărilor încrucișate al temei','Number of cross-sell items to display on the cart page' => 'Numărul de articole de vânzare încrucișată care urmează să fie afișate pe pagina coșului de cumpărături','Add widget areas to the cart page' => 'Adăugați zone widget la pagina coșului','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Aceste zone de widget-uri sunt utilizate pentru a adăuga simboluri de încredere și insigne de încredere pe pagina coșului.','Checkout' => 'Checkout','Checkout layout' => 'Layout de checkout','Design template' => 'Șablon de design','Dark mode' => 'Modul întunecat','Enable dark mode' => 'Activați modul întunecat','Logo image' => 'Imagine logo','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Alegeți o imagine care să fie afișată pe antetul paginii de plată. Se aplică numai atunci când utilizați antetul și subsolul fără distragere.','Header background color' => 'Culoarea de fundal a antetului','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Alegeți o culoare de fundal pentru antetul paginii de checkout. Se aplică numai atunci când utilizați antetul și subsolul fără distragere.','HTML color value. ie: #f3f3f3' => 'Valoarea culorii HTML. de ex: #f3f3f3','Page background color' => 'Culoarea de fundal a paginii','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Alegeți o culoare de fundal pentru pagina de checkout. Culoarea este aplicată elementului <em>body</em>.','Footer background color' => 'Culoarea de fundal a footer-ului','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Alegeți o culoare de fundal pentru subsolul paginii de checkout. Se aplică numai atunci când utilizați antetul și subsolul fără distragere.','Progress bar' => 'Bara de progres','Display the checkout progress bar when using multi-step checkout layout' => 'Afișați bara de progres a comenzii atunci când utilizați aspectul comenzii în mai multe etape','Make the checkout progress bar stay visible while scrolling' => 'Faceți ca bara de progres a comenzii să rămână vizibilă în timpul derulării','Express checkout' => 'Checkout expres','Enable the express checkout section' => 'Activați secțiunea de checkout expres','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Afișează secțiunea de plată rapidă la finalizarea comenzii atunci când gateway-urile de plată acceptate au această caracteristică activată.','Display express checkout buttons in one line for larger screens' => 'Afișați butoanele de plată rapidă pe o singură linie pentru ecrane mai mari','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Ignorați câmpurile suplimentare obligatorii pentru checkout atunci când plătiți cu un gateway de plată compatibil cu checkout expres','Make the order summary stay visible while scrolling' => 'Faceți ca rezumatul comenzii să rămână vizibil în timpul derulării','Choose a background color for the order summary section.' => 'Alegeți o culoare de fundal pentru secțiunea de rezumat al comenzii.','Highlight the order totals row in the order summary table' => 'Evidențiați rândul de totaluri ale comenzii în tabelul de rezumat al comenzii','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Cel mai util atunci când secțiunea de rezumat al comenzii nu are o culoare de fundal evidențiată. S-ar putea aplica, de asemenea, paginilor Coș, Comanda primită și Vizualizare comandă atunci când utilizați Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'Link de acțiune pe sumarul comenzii la finalizarea comenzii.','Edit cart link' => 'Editare link coș','Cart items count' => 'Numărul de articole din coș','Link to shop page' => 'Link către pagina magazinului','Cart items' => 'Articole din coș','Hide cart items errors at the checkout page' => 'Ascundeți erorile articolelor din coș la pagina de checkout','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Nu afișați mesajul de eroare privind articolele din coș în partea de sus a paginii de plată. Atunci când trimiteți formularul de plată pentru a finaliza achiziția, aceste mesaje de eroare vor fi întotdeauna afișate.','Place order' => 'Plasați comanda','Define the position to display "Place order" and terms checkbox section.' => 'Definiți poziția de afișare a secțiunii "Plasați comanda" și a căsuței de verificare a termenilor.','Some options might not be compatible with some plugins and themes.' => 'Este posibil ca unele opțiuni să nu fie compatibile cu anumite pluginuri și teme.','Below the payment section' => 'Sub secțiunea de plată','Below the order summary' => 'Sub rezumatul comenzii','Both below the payment section and the order summary' => 'Atât sub secțiunea de plată, cât și sub rezumatul comenzii','Add widget areas to the checkout page' => 'Adăugați zone de widget-uri la pagina de checkout','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Aceste zone widget sunt utilizate pentru a adăuga simboluri de încredere și insigne de încredere pe pagina de plată.','Display the coupon codes section title' => 'Afișați titlul secțiunii coduri promoționale','Select position where to display the coupon codes section on the checkout page.' => 'Selectați poziția în care să afișați secțiunea coduri promoționale pe pagina de checkout.','Before the checkout steps' => 'Înainte de etapele de plată','As a substep before payment methods' => 'Ca substep înainte de metodele de plată','As a substep after payment methods' => 'Ca substep după metodele de plată','Default button style' => 'Stilul implicit al butonului','"Add" link button' => 'Butonul de legătură "Adaugă"','Checkout fields' => 'Câmpuri de checkout','Optional fields' => 'Câmpuri opționale','Hide optional fields behind a link button' => 'Ascunderea câmpurilor opționale în spatele unui buton de legătură','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Este recomandat să păstrați această opțiune bifată pentru a reduce numărul de câmpuri de introducere deschise, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">citiți cercetarea</a>.','Do not hide "Address line 2" fields behind a link button' => 'Nu ascundeți câmpurile "Linia de adresă 2" în spatele unui buton de legătură','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Recomandat numai atunci când majoritatea clienților au nevoie de câmpul "Linia de adresă 2" sau atunci când obținerea adresei de expediere corecte este esențială (de exemplu, în cazul livrării de alimente și alte produse perisabile).','Billing address' => 'Adresa de facturare','Select position where to display the billing address section on the checkout page.' => 'Selectați poziția în care să afișați secțiunea privind adresa de facturare pe pagina de plată.','As a step before shipping' => 'Ca un pas înainte de expediere','As a sub-step before the shipping address section' => 'Ca o etapă secundară înainte de secțiunea privind adresa de expediere','As a sub-step after the shipping address section' => 'Ca un pas secundar după secțiunea privind adresa de expediere','As a step after shipping' => 'Ca o etapă după expediere','As a sub-step before the payment section' => 'Ca o etapă secundară înaintea secțiunii de plată','Force billing and shipping addresses to the same (single section)' => 'Forțați adresele de facturare și de expediere să fie aceleași (secțiune unică)','Checkbox for "Same as shipping/billing address" checked by default' => 'Caseta de selectare pentru "Aceeași ca adresa de expediere/facturare" bifată implicit','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Caseta de selectare "Aceeași ca adresa de expediere" va începe să fie bifată în mod implicit atunci când secțiunea privind adresa de expediere este afișată prima. <Căsuța de selectare "Aceeași ca adresa de facturare" va începe să fie bifată în mod implicit atunci când secțiunea cu adresa de facturare este afișată prima. <br> Se recomandă să lăsați această opțiune bifată pentru a reduce semnificativ numărul de câmpuri de intrare deschise la finalizarea comenzii, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">citiți cercetarea</a>.','Highlight the billing address section in the checkout form' => 'Evidențiați secțiunea privind adresa de facturare în formularul de plată','Shipping address' => 'Adresa de expediere','Highlight the shipping address section in the checkout form' => 'Evidențiați secțiunea privind adresa de expediere în formularul de plată','Shipping methods' => 'Metode de expediere','Choose in which position to display the shipping methods section.' => 'Alegeți în ce poziție să afișați secțiunea metode de expediere.','Before shipping address' => 'Înainte de adresa de expediere','After shipping address' => 'După adresa de expediere','Local pickup' => 'Ridicare locală','Removes shipping address section when a local pickup shipping method is selected.' => 'Elimină secțiunea privind adresa de expediere atunci când este selectată o metodă de expediere cu preluare locală.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Înlocuiește adresa de expediere cu locația punctului de preluare atunci când este selectată o metodă de expediere cu preluare locală.','Choose which address to save as the shipping address for local pickup orders.' => 'Alegeți ce adresă să salvați ca adresă de expediere pentru comenzile de preluare locală.','Save the selected pickup location' => 'Salvați locația de preluare selectată','Save same as the billing address' => 'Salvați aceeași ca adresa de facturare','Do not save any shipping address' => 'Nu salvați nicio adresă de expediere','Company name field for shipping address' => 'Câmpul Nume companie pentru adresa de expediere','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Schimbați vizibilitatea câmpului cu numele companiei pentru secțiunea cu adresa de expediere din formularul de plată.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Dacă câmpul este setat ca "opțional", care este starea de vizibilitate implicită, nu se va aplica nicio modificare pentru a permite altor plugin-uri să aplice orice modificări de care au nevoie.','Hidden (remove field)' => 'Ascuns (eliminați câmpul)','Optional' => 'Opțional','Required' => 'Necesar','Add shipping phone field to the checkout form.' => 'Adăugați câmpul de telefon pentru expediere la formularul de plată.','Choose in which step to display the shipping phone field.' => 'Alegeți în ce etapă să afișați câmpul telefon de expediere.','Contact step' => 'Pas de contact','Billing phone' => 'Telefon de facturare','Add billing phone field to the checkout form.' => 'Adăugați câmpul telefonic de facturare la formularul de plată.','Choose in which step to display the billing phone field.' => 'Alegeți în ce etapă să afișați câmpul telefon de facturare.','Show country code beside the flag' => 'Afișați codul țării lângă steag','Show an example of a valid phone number inside phone fields' => 'Afișați un exemplu de număr de telefon valid în câmpurile telefonice','Do not change placeholders' => 'Nu modificați marcatorii de poziție','Show if not defined' => 'Afișați dacă nu este definit','Always show' => 'Afișați întotdeauna','Order notes' => 'Note de comandă','Define the visibility of the additional order notes field.' => 'Definiți vizibilitatea câmpului de note de comandă suplimentare.','Gift options' => 'Opțiuni de cadouri','Allow customers to add a gift message and other gift related options to the order.' => 'Permiteți clienților să adauge un mesaj cadou și alte opțiuni legate de cadou la comandă.','Display the gift message as part of the order details table instead of a separate section' => 'Afișați mesajul cadou ca parte a tabelului cu detaliile comenzii în loc de o secțiune separată','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Această opțiune afectează pagina de confirmare a comenzii (pagina de mulțumire) și detaliile comenzii de pe paginile de cont, e-mailurile și bonurile de livrare.','Account matching' => 'Potrivirea conturilor','Enable the account matching feature' => 'Activați funcția de potrivire a conturilor','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Asocierea comenzilor clientului invitat cu contul existent al acestuia, în cazul în care există deja un cont cu datele de contact ale clientului.','Display message when an account exists with the email address provided' => 'Afișați un mesaj atunci când există un cont cu adresa de e-mail furnizată','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Înlocuiește câmpurile de creare a contului cu o notificare și o opțiune de conectare. În anumite contexte, ar putea fi recomandat să lăsați această opțiune dezactivată pentru a proteja confidențialitatea clienților.','Dashboard' => 'Tablou de bord','Integrations' => 'Integrări','License keys' => 'Chei de licență','Visit our website for more information about our plugins and add-ons.' => 'Vizitați site-ul nostru web pentru mai multe informații despre plugin-urile și suplimentele noastre.','Order pay page' => 'Pagina de plată a comenzii','Order pay' => 'Comanda de plată','Enable order pay page optimizations' => 'Activați optimizările paginii de plată a comenzilor','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Modifică aspectul paginii de plată a comenzii pentru comenzile existente care așteaptă plata de la client.','Add widget areas to the order pay page' => 'Adăugați zone widget la pagina de plată a comenzii','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Aceste zone widget sunt utilizate pentru a adăuga simboluri de încredere și insigne de încredere pe pagina de plată a comenzii.','Thank you page & order details layout' => 'Pagina de mulțumire și aspectul detaliilor comenzii','Order details optimizations' => 'Optimizarea detaliilor comenzii','Enable thank you page and order details optimizations' => 'Activați optimizarea paginii de mulțumire și a detaliilor comenzii','Changes the layout of order details on the thank you page and account pages.' => 'Modifică aspectul detaliilor comenzii pe pagina de mulțumire și pe paginile de cont.','Enable order details customizations on email notifications' => 'Activați personalizarea detaliilor comenzii pe notificările prin e-mail','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Afișați secțiuni noi și modificați ordinea secțiunilor în notificările prin e-mail. Stilurile detaliilor comenzii pe notificările prin e-mail rămân neschimbate.','Thank you page' => 'Mulțumesc pagina','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Aceste opțiuni afectează pagina de mulțumire, cunoscută și ca pagini de primire sau confirmare a comenzii.','Order details layout' => 'Layout detalii comandă','Display the order details with wide layout on the thank you page' => 'Afișarea detaliilor comenzii cu aspect larg pe pagina de mulțumire','Add widget areas to the thank you page' => 'Adăugați zone widget la pagina de mulțumire','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Aceste zone de widget-uri sunt utilizate pentru a adăuga simboluri de încredere și insigne de încredere pe pagina de mulțumire.','Order actions' => 'Acțiuni de comandă','Choose in which position to display the order actions.' => 'Alegeți în ce poziție să afișați acțiunile de comandă.','Inside the order overview' => 'În prezentarea generală a comenzii','After the order overview' => 'După prezentarea generală a comenzii','After order sections' => 'Secțiuni după comandă','Order status' => 'Stadiul comenzii','Display the order status progress bar' => 'Afișați bara de progres a stării comenzii','Choose in which position to display the section.' => 'Alegeți în ce poziție să afișați secțiunea.','After the order overview and payment instructions' => 'După prezentarea generală a comenzii și instrucțiunile de plată','Before the order items section' => 'Înainte de secțiunea elemente de comandă','Inside the order items section' => 'În interiorul secțiunii Articole de comandă','After the order items section' => 'După secțiunea elemente de comandă','On the sidebar' => 'Pe bara laterală','Order downloads' => 'Descărcări de comandă','Gift message' => 'Mesaj cadou','Tools' => 'Instrumente','Troubleshooting' => 'Rezolvarea problemelor','Debug options' => 'Opțiuni de depanare','Debug mode' => 'Modul de depanare','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Utilizarea modului de depanare afectează performanța site-ului. Utilizați această opțiune numai în timpul depanării.','Load unminified assets' => 'Încărcați activele neminificate','Enhanced select fields' => 'Câmpuri de selectare îmbunătățite','Fix automatic zoom-in on form fields' => 'Fixare zoom-in automat pe câmpurile de formular','Set <code>font-size</code> inside form fields to 16px' => 'Setați <code>font-size</code> în interiorul câmpurilor de formular la 16px','Fluid Checkout' => 'Verificarea fluidelor','Settings' => 'Setări','Support' => 'Sprijin','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Actualizați la PRO</a> pentru a debloca mai multe opțiuni.','(PRO)' => '(PRO)','(experimental)' => '(experimental)','Please verify your phone number.' => 'Vă rugăm să vă verificați numărul de telefon.','The Bluehost Plugin' => 'Plugin-ul Bluehost','Custom fields' => 'Câmpuri personalizate','Enable custom shipping email field' => 'Activați câmpul de e-mail de expediere personalizat','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Atunci când este activat, câmpul e-mail de expediere din pluginul Bluehost va fi adăugat la formularul de plată.','Captcha Pro by BestWebSoft' => 'Captcha Pro de BestWebSoft','Captcha position' => 'Poziția Captcha','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Definiți poziția de afișare a secțiunii captcha. Unele poziții pot să nu funcționeze în funcție de tipul de captcha ales.','Selecting a pickup point is required before proceeding.' => 'Selectarea unui punct de preluare este necesară înainte de a continua.','Pickup point' => 'Punct de preluare','Pickup point not selected yet.' => 'Punctul de preluare nu a fost selectat încă.','Pickup point:' => 'Punct de preluare:','Mailchimp for WooCommerce' => 'Mailchimp pentru WooCommerce','Subscribe checkbox' => 'Caseta de selectare Abonare','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Suprascrieți poziția căsuței de selectare a abonamentului pe pagina de checkout și afișați-o întotdeauna pe pasul de contact','Before Shipping Address' => 'Înainte de adresa de expediere','(originally "%s")' => '(inițial "%s")','After Shipping Address' => 'După adresa de expediere','Selecting a collection point is required when shipping with FermoPoint.' => 'Selectarea unui punct de colectare este necesară la expedierea cu FermoPoint.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Dacă este bifată, informează utilizatorii cu privire la greșelile de scriere în e-mail. (Această caracteristică a fost dezactivată deoarece Fluid Checkout oferă această caracteristică. Modificările aduse acestei opțiuni nu vor avea efect)','Enable Mail Check: (disabled feature)' => 'Enable Mail Check: (caracteristică dezactivată)','Carrier:' => 'Transportator:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce Email Marketing','Sign up checkbox position' => 'Poziția căsuței de selectare pentru înscriere','Move the sign up checkbox to the contact step' => 'Mutați caseta de selectare pentru înscriere la etapa de contact','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Atunci când este activată, caseta de selectare va fi mutată la pasul de contact independent de locația de afișare definită în setările pluginului Sendinblue.','Theme Betheme' => 'Temă Betheme','Checkout progress' => 'Progresul checkout-ului','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Afișați secțiunea pași de plată din Betheme pe paginile de plată, coș și comandă primită.','Theme Fennik' => 'Tema Fennik','Breadcrumbs' => 'Firimituri de pâine','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Scoateți secțiunea breadcrumbs din tema Fennik atunci când utilizați antetul și subsolul Fluid Checkout.','Theme Go' => 'Tema Go','My account layout' => 'Aspectul contului meu','Enable wide layout on "My account" page.' => 'Activați aspectul larg pe pagina "Contul meu".','Theme Impreza' => 'Tema Impreza','Header' => 'Antet','Spacing for site header at the checkout page (in pixels)' => 'Spațiere pentru antetul site-ului la pagina de plată (în pixeli)','Only applicable when using the Impreza theme header at the checkout page.' => 'Se aplică numai atunci când utilizați antetul temei Impreza la pagina de plată.','Theme Kapee' => 'Tema Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Afișați secțiunea pași de finalizare a comenzii din tema Kapee pe paginile de finalizare a comenzii, coș și comandă primită.','Theme Porto' => 'Tema Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Afișați secțiunea pași de finalizare a comenzii din tema Porto pe paginile de finalizare a comenzii, coș și comandă primită.','Theme Pressmart' => 'Tema Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Afișați secțiunea pași de plată din tema Pressmart pe paginile de plată, coș și comandă primită.','Theme The Gem' => 'Tema gemului','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Ieșirea secțiunii Pași de plată din tema The Gem atunci când utilizați antetul și subsolul Fluid Checkout.','Theme Woodmart' => 'Tema Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Scoateți secțiunea pașilor de plată din tema Woodmart atunci când utilizați antetul și subsolul Fluid Checkout.','Checkout options' => 'Opțiuni de checkout','Disable the theme checkout options' => 'Dezactivați opțiunile de checkout ale temei','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Opțiunile afișare imagine produs, câmp cantitate, buton eliminare și link către pagina produsului adăugate de temă sunt dezactivate implicit.','Theme Atomion' => 'Tema Atomion','Order progress' => 'Progresul comenzii','Display order progress from the theme' => 'Afișarea progresului comenzii din temă','Display the form field labels visible on the page' => 'Afișați etichetele câmpurilor de formular vizibile pe pagină','It is recommended to keep this option enabled for a better user experience.' => 'Este recomandat să păstrați această opțiune activată pentru o experiență mai bună a utilizatorului.','Theme ZK Nito' => 'Tema ZK Nito','Add extra fields to the checkout form' => 'Adăugați câmpuri suplimentare la formularul de plată','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Adaugă un e-mail de expediere suplimentar și un câmp de telefon de expediere la secțiunea adresă de expediere.','Go to the home page' => 'Mergeți la pagina de pornire','Skip to content' => 'Salt la conținut','Create an account' => 'Creați un cont','Log in to your account' => 'Conectați-vă la contul dvs.','Already have an account?' => 'Aveți deja un cont?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Conectat ca %1$s. <a href="%2$s">Leg out</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Comanda dvs. are o sumă totală datorată de %s. Nu este necesară nicio altă plată.','Close and continue with checkout' => 'Închideți și continuați cu finalizarea comenzii','Continue' => 'Continuați','Parcel terminal' => 'Terminal de colete','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Acest widget a fost înlocuit de Fluid Checkout. </p><p>Când utilizați Fluid Checkout, pagina de checkout trebuie să utilizeze codul scurt original WooCommerce <code>[woocommerce_checkout]</code> pentru a funcționa corect.</p><p>Pentru mai multe informații, vizitați documentația Fluid Checkout.</p>','Theme The7' => 'Tema The7','Additional header sections' => 'Secțiuni de antet suplimentare','Output additional header sections if enabled in the theme settings.' => 'Afișează secțiuni de antet suplimentare dacă sunt activate în setările temei.','More information' => 'Mai multe informații','Pick a Locker' => 'Alege un dulap','Page template' => 'Șablon de pagină','Use `Order confirmation` page template for block-based themes' => 'Utilizați șablonul de pagină `Confirmare comandă` pentru temele bazate pe blocuri','Only applies when using a block-based theme.' => 'Se aplică numai atunci când se utilizează o temă bazată pe blocuri.','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'Formular de plată','Apply styles to the Stripe payment form fields' => 'Aplicați stiluri câmpurilor formularului de plată Stripe','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Atunci când este activat, Fluid Checkout va aplica stiluri optimizate pentru compatibilitatea cu pluginul. Este posibil să doriți să dezactivați această opțiune dacă utilizați stiluri personalizate pentru câmpurile formularului de plată Stripe.','Theme Nyture' => 'Tema Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Scoateți secțiunea pași de plată din tema Nyture atunci când utilizați Fluid Checkout.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Permite clienților să efectueze plăți pentru comenzi care sunt create manual de administratorul magazinului sau care nu sunt finalizate în timpul procesului de checkout.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Pluginul WooCommerce Checkout Manager by Quadlayers nu este compatibil cu Fluid Checkout','Company name field for billing address' => 'Câmpul Nume companie pentru adresa de facturare','Change visibility for the company name field for the billing address section on the checkout form.' => 'Schimbați vizibilitatea câmpului Nume companie pentru secțiunea Adresa de facturare din formularul de plată.','Theme Bookshelf' => 'Raft tematic','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Scoateți secțiunea pași de plată din tema Bookshelf atunci când utilizați Fluid Checkout.','Account password' => 'Parola contului','An account will be created with the information provided at checkout when completing the order.' => 'Un cont va fi creat cu informațiile furnizate la finalizarea comenzii.','Choose the style of the progress bar.' => 'Alegeți stilul barei de progres.','Bars' => 'Bare','Theme Ireca' => 'Tema Ireca','WooCommerce page layout' => 'Aspectul paginii WooCommerce','Force wide layout on WooCommerce pages' => 'Forțați aspectul larg pe paginile WooCommerce','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Acest lucru asigură că secțiunea de conținut nu este prea îngustă pe paginile WooCommerce, inclusiv paginile de checkout, coș, comandă primită, plată comandă și cont.','WooCommerce Smart Coupons' => 'Cupoane inteligente WooCommerce','Position on checkout page' => 'Poziția pe pagina de checkout','Choose where to display the available coupons section on the checkout page.' => 'Alegeți unde să afișați secțiunea cupoane disponibile pe pagina de checkout.','Before the progress bar' => 'Înainte de bara de progres','After the progress bar' => 'După bara de progres','Before coupon codes section' => 'Înainte de secțiunea coduri promoționale','Format phone numbers according to the rules for each country.' => 'Formatați numerele de telefon în conformitate cu normele din fiecare țară.','Use precise phone number validation' => 'Utilizați validarea exactă a numărului de telefon','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Aceasta este o caracteristică experimentală și este posibil să nu funcționeze conform așteptărilor în toate configurațiile. Utilizați-o cu precauție.','Phone number validation types used when precise validation is enabled.' => 'Tipuri de validare a numărului de telefon utilizate atunci când validarea precisă este activată.','Mobile' => 'Mobil','Fixed line' => 'Linie fixă','Toll free' => 'Apel gratuit','Or' => 'Sau','Contact' => 'Persoană de contact','Multi step' => 'Mai multe etape','2 columns' => '2 coloane','1 column' => '1 coloană','Before checkout steps' => 'Pași înainte de checkout','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Atunci când se utilizează aspectul de plată <em>"1 coloană"</em>, această opțiune este întotdeauna setată la <em>"Înainte de etapele de plată"</em> și se aplică, de asemenea, la vizualizarea desktop.','Position for the extra order summary section on mobile.' => 'Poziția pentru secțiunea suplimentară de rezumat al comenzii pe mobil.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'Opțiunea <em>"Pe antetul site-ului"</em> se aplică numai atunci când se utilizează antetul fără distragere a atenției.','On the site header (requires distraction-free header)' => 'Pe antetul site-ului (necesită un antet care să nu distragă atenția)','Initial state for the expansible order summary section on mobile.' => 'Starea inițială pentru secțiunea expansibilă de rezumat al comenzii pe mobil.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Vă recomandăm să o setați ca <em>expanded</em> pentru următoarele țări din cauza cerințelor de reglementare: <strong>Germania</strong>, <strong>Austria</strong>, <strong>Suedia</strong>, <strong>Țările de Jos</strong>, <strong>Polonia</strong>, <strong>Belgia</strong> și <strong>Franța</strong>.','Collapsed' => 'Colapsat','Expanded' => 'Extinse','Do not show' => 'Nu afișați','yes' => 'da','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Câmpul pentru numărul de telefon de livrare poate fi setat ca „obligatoriu” dacă secțiunea adresă de facturare este afișată după secțiunea adresă de livrare, iar câmpul pentru numărul de telefon de facturare este setat ca „obligatoriu”. Acest lucru este necesar pentru a asigura că adresa de livrare poate fi copiată în adresa de facturare atunci când această opțiune este bifată; în caz contrar, clientul ar putea să nu poată finaliza formularul de finalizare a comenzii.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Câmpul „Număr de telefon pentru facturare” poate fi setat ca „obligatoriu” dacă secțiunea „Adresă de facturare” este afișată înaintea secțiunii „Adresă de livrare”, iar câmpul „Număr de telefon pentru livrare” este setat ca „obligatoriu”. Acest lucru este necesar pentru a asigura că adresa de livrare poate fi copiată în adresa de facturare atunci când această opțiune este bifată; în caz contrar, clientul ar putea să nu poată finaliza formularul de finalizare a comenzii.','Settings profiles' => 'Profiluri de setări','Settings profile' => 'Profil de setări','You do not have permission to perform this action.' => 'Nu aveți permisiunea de a efectua această acțiune.','You do not have permission to activate plugins.' => 'Nu aveți permisiunea de a activa pluginuri.','Missing plugin.' => 'Plugin lipsă.','Plugin activated.' => 'Pluginul a fost activat.','The following changes will be applied:' => 'Se vor aplica următoarele modificări:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Începând cu Fluid Checkout 5.0, setările sunt salvate într-un mod diferit. Opțiunile vechi sunt încă stocate în baza de date pentru a permite, dacă este necesar, revenirea la versiunile anterioare.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Magazinul tău funcționează de aproximativ două săptămâni cu noile setări, astfel încât ai putut curăța opțiunile vechi stocate în baza de date. Te rugăm să reții că, după curățare, dacă va fi necesar să revii la versiunile anterioare ale pluginului, acesta va utiliza valorile implicite pentru toate setările.','Fluid Checkout settings cleanup' => 'Curățarea setărilor pentru „Fluid Checkout”','Delete leftover options' => 'Ștergeți opțiunile rămase','Help us improve Fluid Checkout' => 'Ajută-ne să îmbunătățim Fluid Checkout','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Partajați rapoarte anonime privind mediul de utilizare a site-ului prin Fluid Checkout pentru a beneficia de asistență mai rapidă și pentru a ne ajuta să îmbunătățim compatibilitatea și să evaluăm impactul. Nu sunt incluse date referitoare la clienți, utilizatori sau date sensibile. Puteți alege oricând ce informații doriți să partajați din setările din secțiunea „Instrumente”.','Enable site environment reports' => 'Activați rapoartele privind mediul site-ului','Review settings' => 'Verifică setările','This preview has expired. Reload the admin page to start a new preview.' => 'Această previzualizare a expirat. Reîncarcă pagina de administrare pentru a începe o nouă previzualizare.','Preview expired' => 'Previzualizarea a expirat','Orders cannot be placed in the preview.' => 'În modul de previzualizare nu se pot plasa comenzi.','Logging in is not available in the preview.' => 'Autentificarea nu este disponibilă în versiunea de previzualizare.','Accounts cannot be created in the preview.' => 'În modul de previzualizare nu se pot crea conturi.','Requests to other sites are blocked in the preview.' => 'În modul de previzualizare, cererile către alte site-uri sunt blocate.','Processing…' => 'Se procesează…','Something went wrong. Please try again.' => 'A apărut o eroare. Vă rugăm să încercați din nou.','Activate plugin' => 'Activează pluginul','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO – Pachetul complet pentru procesul de finalizare a comenzii','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Toate funcțiile PRO + toate suplimentele, la un singur preț. Șabloane de design, pagini optimizate pentru coșul de cumpărături și confirmarea comenzii, sincronizarea conturilor și multe altele.','Optimized order pay page' => 'Pagina optimizată de plată a comenzii','Express checkout buttons from supported payment methods' => 'Butoane de finalizare rapidă a comenzii pentru metodele de plată acceptate','Delayed account creation' => 'Crearea contului a fost amânată','Address autocomplete with Google Maps APIs' => 'Completarea automată a adreselor cu ajutorul API-urilor Google Maps','Multiple saved addresses with the address book' => 'Mai multe adrese salvate în agenda de adrese','EU-VAT assistant' => 'Asistent TVA UE','Hide this section' => 'Ascunde această secțiune','Learn more' => 'Află mai multe','Get early access' => 'Obțineți acces anticipat','Activate add-on' => 'Activează extensia','Get more out of your checkout journey' => 'Profitați la maximum de experiența de finalizare a comenzii','Test API key' => 'Testare cheie API','Guided setup' => 'Configurare asistată','Options' => 'Opțiuni','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Configurați aspectul și designul în secțiunea <a href="%s">opțiuni de finalizare a comenzii</a>.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Activați opțiunea de finalizare a comenzii fără cont și/sau verificați <a href="%s">setările conturilor clienților</a>.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Activează paginile optimizate <a href="%1$s">coș de cumpărături</a>, <a href="%2$s">mulțumire</a> și <a href="%3$s">plată comandă</a>.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Activează <a href="%s">completarea automată a adreselor</a> din Google Maps.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Activați opțiunea de a salva mai multe adrese cu ajutorul <a href="%s">agendei de adrese</a>.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Verificați dacă există <a href="%s">opțiuni de integrare</a> disponibile pentru tema respectivă sau pentru alte pluginuri pe care le-ați instalat.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Beneficiați de asistență mai rapidă și ajutați-ne să îmbunătățim compatibilitatea și să evaluăm impactul. <a href="%s">Activați urmărirea utilizării</a> din setările instrumentelor.','Missing settings tab.' => 'Lipsește fila „Setări”.','Getting started' => 'Noțiuni introductive','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Excelent! Pagina ta de finalizare a comenzii rulează acum pe Fluid Checkout.</strong> Iată câțiva pași pentru a începe:','Completed' => 'Finalizat','Preview report data' => 'Previzualizare date din raport','Send now' => 'Trimite acum','Auto-detect' => 'Detectare automată','Afrikaans' => 'afrikaans','Albanian' => 'albaneză','Amharic' => 'amharică','Arabic' => 'Arabă','Armenian' => 'armeană','Azerbaijani' => 'azerbaidjană','Basque' => 'bască','Belarusian' => 'belarusă','Bengali' => 'bengaleză','Bosnian' => 'bosniac','Bulgarian' => 'bulgară','Burmese' => 'birmaneză','Catalan' => 'catalană','Chinese' => 'chineză','Chinese (Simplified)' => 'Chineză (simplificată)','Chinese (Hong Kong)' => 'Chineză (Hong Kong)','Chinese (Traditional)' => 'Chineză (tradițională)','Croatian' => 'croată','Czech' => 'cehă','Danish' => 'daneză','Dutch' => 'Olandeză','English' => 'Engleză','English (Australian)' => 'Engleză (australiană)','English (Great Britain)' => 'Engleză (Marea Britanie)','Estonian' => 'estonă','Farsi' => 'Farsi','Finnish' => 'finlandeză','Filipino' => 'Filipineză','French' => 'Franceză','French (Canadian)' => 'Franceză (canadiană)','Galician' => 'galiciană','Georgian' => 'georgiană','German' => 'Germană','Greek' => 'Greacă','Gujarati' => 'gujarati','Hebrew' => 'ebraică','Hindi' => 'Hindi','Hungarian' => 'maghiară','Icelandic' => 'islandeză','Indonesian' => 'indoneziană','Italian' => 'italiană','Japanese' => 'Japoneză','Kannada' => 'Kannada','Kazakh' => 'kazah','Khmer' => 'khmeră','Korean' => 'Coreeană','Kyrgyz' => 'Kârgâz','Lao' => 'Lao','Latvian' => 'letonă','Lithuanian' => 'lituaniană','Macedonian' => 'macedoneană','Malay' => 'malayeză','Malayalam' => 'malayalamă','Marathi' => 'marathi','Mongolian' => 'mongolă','Nepali' => 'nepală','Norwegian' => 'norvegiană','Polish' => 'poloneză','Portuguese' => 'portugheză','Portuguese (Brazil)' => 'Portugheză (Brazilia)','Portuguese (Portugal)' => 'Portugheză (Portugalia)','Punjabi' => 'punjabi','Romanian' => 'română','Russian' => 'Rusa','Serbian' => 'sârbă','Sinhalese' => 'cingaleză','Slovak' => 'slovacă','Slovenian' => 'slovenă','Spanish' => 'Spaniolă','Spanish (Latin America)' => 'Spaniolă (America Latină)','Swahili' => 'swahili','Swedish' => 'Suedeză','Tamil' => 'Tamilă','Telugu' => 'Telugu','Thai' => 'tailandeză','Turkish' => 'Turcă','Ukrainian' => 'ucraineană','Urdu' => 'Urdu','Vietnamese' => 'vietnameză','Zulu' => 'Zulu','Google address autocomplete' => 'Completarea automată a adreselor de către Google','Google Places API version' => 'Versiunea API-ului Google Places','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Alegeți versiunea API-ului Google Places pe care doriți să o utilizați. Vă recomandăm să treceți la noul API Places cât mai curând posibil.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Vă recomandăm să utilizați „Places API (New)”, întrucât, începând cu 1 martie 2025, Google va trece versiunea „Places API (Legacy)” la statutul de versiune învechită, ceea ce înseamnă că nu veți mai putea activa acest serviciu pentru cheile API noi și că, în cele din urmă, acea versiune a API-ului nu va mai fi disponibilă. Conturile existente care utilizează deja API-ul vechi vor putea continua să funcționeze fără întreruperi.','(Recommended)' => '(Recomandat)','Google API key' => 'Cheia API Google','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Introduceți cheia API Google și folosiți butonul de testare pentru a verifica dacă funcționează pentru acest site web. Asigurați-vă că cheia este valabilă și autorizată pentru domeniul dvs.; în caz contrar, câmpul de adresă ar putea fi blocat, împiedicând clienții să-și finalizeze comenzile.','Enable Google address autocomplete' => 'Activează completarea automată a adreselor de către Google','Enable address autocompletion using the Google Maps APIs.' => 'Activați completarea automată a adreselor folosind API-urile Google Maps.','Google API language' => 'Limbajul API-ului Google','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Această limbă va fi utilizată pentru afișarea sugestiilor de adrese din API-ul Google Places, iar adresele vor fi completate automat în această limbă.','Result types' => 'Tipuri de rezultate','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Lăsați câmpul gol pentru a accepta orice tip de rezultate, ceea ce duce de obicei la rezultate mai relevante. <a href="%s" target="_blank">Consultați documentația pentru mai multe detalii</a>. <br>Selectați până la 5 tipuri de rezultate ale căutării de adrese care să fie afișate în câmpurile de completare automată a adreselor. <br>Accesați documentația Google Maps pentru a afla mai multe despre <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">tipurile acceptate</a>.','Result types (Legacy API)' => 'Tipuri de rezultate (API vechi)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Ce tip de rezultate ale căutării de adrese trebuie returnate atunci când se utilizează API-ul Places (versiunea veche). <br>Consultați documentația API-ului Google Places (versiunea veche) pentru a afla mai multe despre <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">tipurile acceptate</a>.','Company fields' => 'Câmpuri ale companiei','Enable autocomplete for the company name if available' => 'Activează completarea automată pentru numele companiei, dacă este disponibilă','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Activați completarea automată a câmpului „companie” cu informațiile privind denumirea companiei atunci când acestea sunt returnate de API-urile Google Maps.','Business search' => 'Căutare de companii','Enable search for businesses in the company field' => 'Activează căutarea firmelor în câmpul „Companie”','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Activează afișarea sugestiilor de adrese asociate unei companii atunci când se introduce text în câmpul „Companie”, apoi completează automat toate câmpurile de adresă atunci când se selectează o companie din lista de sugestii.','Company result types' => 'Tipuri de rezultate ale companiei','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Selectați până la 5 tipuri de rezultate ale căutării de adrese care să fie afișate la completarea automată a câmpurilor referitoare la companie. <br>Valoarea recomandată este <code>unitate</code>, care include majoritatea tipurilor de întreprinderi. <br>Lăsați câmpul necompletat pentru a accepta orice tip de rezultate, inclusiv cele care nu au legătură cu întreprinderile. <br>Consultați documentația Google Maps pentru a afla mai multe despre <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">tipurile acceptate</a>.','Google logo' => 'Logo-ul Google','Show text and logo "Powered by Google"' => 'Afișează textul și logo-ul „Powered by Google”','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Dacă această opțiune este bifată, textul și sigla „Powered by Google” vor fi afișate în partea de jos a casetei cu sugestii pentru completarea automată a adresei.','Brasil API address autocomplete' => 'Completare automată a adreselor prin API-ul din Brazilia','Brasil API' => 'API-ul Brazil','Enable Brasil API address autocomplete for CEP fields' => 'Activați completarea automată a adreselor prin API-ul Brasil pentru câmpurile CEP','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Utilizați API-ul Brasil pentru a prelua și a completa automat adresele folosind câmpul CEP/Cod poștal. Această funcție este valabilă doar pentru adresele din Brazilia.','API version' => 'Versiunea API-ului','Choose which version of the Brasil API CEP method to use.' => 'Alegeți versiunea metodei CEP din API-ul Brasil pe care doriți să o utilizați.','Address book migration' => 'Migrarea agendei de adrese','WooCommerce addresses' => 'Adrese WooCommerce','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Copiați adresele de livrare și de facturare existente din WooCommerce în agenda de adrese a clienților.','Enable the address book feature' => 'Activați funcția de agendă','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Permiteți clienților să salveze mai multe adrese și să stabilească adresa implicită care va fi utilizată pentru livrare și facturare.','Address labels' => 'Etichete cu adresă','Allow customers to add a custom label for each address' => 'Permiteți clienților să adauge o etichetă personalizată pentru fiecare adresă','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Etichetele de adresă le permit clienților să distingă mai ușor între adresele salvate (de exemplu: „Casa mamei”). Etichetele de adresă sunt confidențiale pentru clienți și nu vor fi afișate sau tipărite pe pagina cu detaliile comenzii sau pe facturi.','Display layout' => 'Aspectul afișajului','Choose how saved addresses are displayed at checkout and on the cart.' => 'Alegeți modul în care sunt afișate adresele salvate la finalizarea comenzii și în coșul de cumpărături.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Se aplică la finalizarea comenzii și în coșul de cumpărături. Adresele salvate pe pagina contului utilizează întotdeauna dispunerea sub formă de carduri.','Address cards' => 'Cărți de vizită','Address list' => 'Lista de adrese','Dropdown field' => 'Câmp cu meniu derulant','Address search' => 'Căutare adresă','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Afișează filtrul de căutare a adreselor în interfața pentru utilizatori atunci când clientul are cel puțin acest număr de adrese salvate disponibile.','Not used when display layout is set to dropdown field.' => 'Nu se utilizează atunci când aspectul afișajului este setat pe câmp derulant.','Addresses' => 'Adrese','Enable cart page optimizations to see more options' => 'Activează optimizările paginii coșului de cumpărături pentru a vedea mai multe opțiuni','Sticky order summary' => 'Rezumatul comenzii (fixat)','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Selectați poziția în care doriți să fie afișată secțiunea cu codurile promoționale pe pagina coșului de cumpărături. Această opțiune este disponibilă numai dacă este activat coșul de cumpărături AJAX și dacă utilizarea codurilor promoționale este activată în setările WooCommerce.','Layout of cross-sell' => 'Structura vânzărilor încrucișate','Cross-sells displayed' => 'Produse conexe afișate','Items' => 'Articole','Cart page optimization' => 'Optimizarea paginii coșului de cumpărături','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Asigură-te că coșul de cumpărături are același aspect clar și orientat spre conversie ca și pagina de finalizare a comenzii.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Asigurați-vă că aspectul coșului de cumpărături se potrivește cu pagina de finalizare a comenzii, pentru a oferi o experiență de cumpărare uniformă.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Asigură-te că coșul de cumpărături este mereu actualizat în fundal, fără reîncărcări complete ale paginii atunci când se modifică cantitățile.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Plasați codurile promoționale, informațiile despre livrare și produsele conexe exact acolo unde generează cele mai bune rezultate.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Mențineți rezumatul comenzii vizibil în timpul derulării și adăugați simboluri de încredere acolo unde cumpărătorii au nevoie de asigurări.','Columns' => 'Coloane','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Stiluri generale pentru etapele procesului de finalizare a comenzii, rezumatul comenzii și alte secțiuni. Se aplică și altor pagini, cum ar fi cele de finalizare a comenzii, coșul de cumpărături, pagina de mulțumire (comanda primită) și pagina de vizualizare a comenzii.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Atunci când se utilizează aspectul <em>„1 coloană”</em> împreună cu șablonul de design <em>„Split”</em>, coloana din dreapta este afișată numai dacă zona de widgeturi din bara laterală a paginii este activă (bara laterală pentru finalizarea comenzii, bara laterală pentru coșul de cumpărături sau bara laterală pentru comenzi primite). În caz contrar, pagina rămâne într-o singură coloană, cu stilurile „Split”.','Split column background' => 'Fundalul coloanelor separate','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Alegeți o culoare de fundal pentru coloana secundară a designului „Split”. Lăsați câmpul necompletat pentru a utiliza culoarea de fundal a rezumatului comenzii.','Page templates' => 'Șabloane de pagină','Checkout template' => 'Șablon pentru finalizarea comenzii','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Recomandat pentru a reduce distragerile în timpul finalizării comenzii. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Citiți studiul despre abandonarea coșului de cumpărături</a>.','Sticky progress bar' => 'Bară de progres fixă','Progress bar style' => 'Stilul barei de progres','Order totals' => 'Totalul comenzilor','Background color' => 'Culoarea de fundal','Action link' => 'Link de acțiune','Mobile order summary' => 'Rezumatul comenzii de pe mobil','Mobile initial state' => 'Starea inițială a dispozitivului mobil','Enable editing cart items at checkout' => 'Activează editarea articolelor din coș la finalizarea comenzii','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Permiteți clienților să modifice cantitățile produselor sau să elimine articole direct de pe pagina de finalizare a comenzii.','Cart item errors' => 'Erori legate de articolele din coș','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Se aplică numai în cazul în care codul promoțional este afișat într-o secțiune separată pe paginile de finalizare a comenzii sau din coșul de cumpărături și dacă utilizarea codurilor promoționale este activată în setările WooCommerce.','Coupon codes position' => 'Poziția codurilor promoționale','Apply coupon button' => 'Butonul „Aplică cuponul”','Select style of the "apply coupon" button.' => 'Alegeți stilul butonului „Aplică cuponul”.','Address line 2' => 'Rândul 2 al adresei','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Această setare este comună pentru secțiunile „Finalizare comandă” și „Ridicare locală”. În secțiunea „Ridicare locală”, aceasta determină, de asemenea, dacă selectorul „Expediere/Ridicare” apare în cadrul secțiunii privind metodele de livrare (înainte de adresă) sau ca o secțiune separată (după aceasta).','Customer accounts' => 'Conturile clienților','Guest checkout' => 'Finalizarea comenzii ca oaspete','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Opțiunile de finalizare a comenzii ca vizitator, de autentificare și de creare a contului din pagina de setări „Conturi” a WooCommerce. Acestea sunt gestionate aici pentru confortul dumneavoastră, astfel încât să puteți utiliza valori diferite pentru fiecare profil de setări.','Allow customers to checkout without an account' => 'Permiteți clienților să finalizeze comanda fără a avea un cont','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Se recomandă</strong> ca clienții să nu fie nevoiți să-și creeze un cont sau să se autentifice în timpul finalizării comenzii, ceea ce poate duce la scăderea ratelor de conversie.','When disabled, customers must log in or create an account to complete the purchase.' => 'Când această opțiune este dezactivată, clienții trebuie să se autentifice sau să-și creeze un cont pentru a finaliza achiziția.','Login at checkout' => 'Autentificare la finalizarea comenzii','Enable log-in during checkout' => 'Activează autentificarea în timpul finalizării comenzii','Show a link for returning customers to log in from the checkout page.' => 'Afișează un link pe pagina de finalizare a comenzii, prin care clienții fideli să se poată autentifica.','Account creation' => 'Crearea unui cont','Allow customers to create an account during checkout' => 'Permiteți clienților să își creeze un cont în timpul procesului de finalizare a comenzii','Customers can create an account before placing their order.' => 'Clienții pot crea un cont înainte de a plasa comanda.','Allow customers to create an account from the My account page' => 'Permiteți clienților să își creeze un cont din pagina „Contul meu”','Customers can register a new account from the My account page.' => 'Clienții își pot crea un cont nou din pagina „Contul meu”.','Username' => 'Nume de utilizator','Generate from customer\'s name' => 'Generare pe baza numelui clientului','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Se recomandă</strong> ca clienții să nu fie nevoiți să aleagă un nume de utilizator în timpul finalizării comenzii, deoarece acest lucru poate reduce ratele de conversie.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Un nume de utilizator este generat pe baza numelui clientului sau, în cazul în care numele nu poate fi utilizat, pe baza adresei de e-mail.','Password' => 'Parolă','Send password setup link' => 'Trimite linkul pentru configurarea parolei','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Se recomandă</strong> ca clienților să nu li se ceară să seteze o parolă în timpul finalizării comenzii, deoarece acest lucru poate reduce ratele de conversie.','Customers receive an email to create their password securely.' => 'Clienții primesc un e-mail prin care li se solicită să-și creeze o parolă în condiții de siguranță.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Permiteți clienților înregistrați să finalizeze procesul de plată fără a se autentifica și asociați comanda cu contul lor existent atunci când datele de contact se potrivesc.','Existing account message' => 'Mesaj privind contul existent','Let customers create an account after placing their order, from the thank you page.' => 'Permiteți clienților să își creeze un cont după ce au plasat comanda, direct de pe pagina de mulțumire.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Opțiunile din această secțiune sunt disponibile atunci când sunt activate funcțiile de finalizare a comenzii ca oaspete și de asociere a conturilor. Activați ambele funcții menționate mai sus pentru a configura crearea contului cu întârziere.','Enable delayed account creation' => 'Activează crearea contului cu întârziere','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Activați crearea contului cu întârziere atunci când sunt activate atât finalizarea comenzii ca oaspete, cât și corelarea conturilor.','Section position' => 'Poziția secțiunii','Before customer details section' => 'Înainte de secțiunea cu detaliile clientului','After customer details section' => 'După secțiunea cu datele clientului','Account creation benefits' => 'Avantajele creării unui cont','Leaving the field empty will display the default text.' => 'Dacă lăsați câmpul necompletat, se va afișa textul implicit.','Inline buttons' => 'Butoane încorporate','Required fields' => 'Câmpuri obligatorii','Enable gift message fields at checkout' => 'Activați câmpurile pentru mesajul de cadou la finalizarea comenzii','Expanded gift message' => 'Mesaj de cadou extins','Display gift message field always expanded' => 'Câmpul pentru mesajul de cadou să fie afișat întotdeauna desfăcut','Gift message in order details' => 'Mesaj de cadou în detaliile comenzii','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'În acest moment nu sunt disponibile integrări în această secțiune. Opțiunile asociate fiecărui plugin și temă vor apărea aici doar atunci când respectivul plugin sau temă este activat(ă).','Phone fields' => 'Câmpuri de telefon','Field visibility' => 'Vizibilitatea pe teren','Field position' => 'Poziția pe teren','Phone country code & validation' => 'Codul de țară al numărului de telefon și validarea acestuia','Country' => 'Țară','Enable country on phone fields' => 'Activați câmpurile referitoare la țară pe telefon','Filter countries for shipping or billing' => 'Filtrează țările pentru livrare sau facturare','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Limitați selectorul de țară din fiecare câmp referitor la numărul de telefon la țările permise pentru livrare sau facturare în magazinul dvs.','Validation' => 'Validare','Enable simple validation based on country rules' => 'Activați validarea simplă pe baza regulilor specifice fiecărei țări','Checks that the phone number is valid for the selected country, including country code and length.' => 'Verifică dacă numărul de telefon este valid pentru țara selectată, inclusiv codul de țară și numărul de cifre.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Verificare mai strictă pentru a se asigura că numărul este un număr valid de telefon mobil, de linie fixă sau de alt tip acceptat pentru țara selectată. Este posibil ca unele numere valide să fie respinse.','Validation types' => 'Tipuri de validare','Placeholders' => 'Simboluri de substituție','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Momentan nu există chei de licență de gestionat. Cheile de licență vor apărea aici atunci când un plugin sau un add-on Fluid Checkout licențiat este activ.','Default delivery type' => 'Tipul de livrare implicit','Choose which delivery type will be selected by default.' => 'Alegeți tipul de livrare care va fi selectat în mod implicit.','Shipping zone fields' => 'Câmpuri privind zonele de livrare','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Alegeți câmpurile care vor fi afișate pentru filtrarea zonelor de livrare cu ridicare locală. Lăsați câmpul gol pentru a afișa toate opțiunile disponibile.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Aceste câmpuri vor fi afișate ca filtru pentru metodele de livrare cu ridicare locală. Este posibil ca unele câmpuri să apară totuși la finalizarea comenzii, chiar dacă nu sunt selectate aici, în cazul în care pluginurile compatibile le necesită pentru a funcționa corect.','Order shipping address' => 'Adresa de livrare a comenzii','Order pay page optimization' => 'Optimizarea paginii de plată a comenzilor','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Asigurați-vă că comenzile neplătite au același aspect clar și orientat spre conversie ca și pagina de finalizare a comenzii.','Optimize the layout of the order pay page for orders pending payment.' => 'Optimizați aspectul paginii de plată a comenzilor pentru comenzile în așteptare de plată.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Adaptați experiența de plată la procesul de finalizare a comenzii pentru a asigura o experiență de cumpărare uniformă.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Adăugați simboluri și insigne care inspiră încredere acolo unde cumpărătorii au nevoie de asigurări înainte de a efectua plata.','Thank you page optimization' => 'Optimizarea paginii de mulțumire','Make the thank you page and order details clearer for customers after they buy.' => 'Asigurați-vă că pagina de mulțumire și detaliile comenzii sunt mai clare pentru clienți după ce aceștia efectuează achiziția.','Optimize the thank you page and account order details with a clearer layout.' => 'Optimizați pagina de mulțumire și detaliile comenzii din cont, folosind un aspect mai clar.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Afișează evoluția stării comenzii, acțiunile, descărcările și notele acolo unde este cazul.','Customize order details sections on email notifications.' => 'Personalizați secțiunile cu detalii despre comandă din notificările prin e-mail.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Adăugați simboluri și insigne care inspiră încredere acolo unde cumpărătorii au nevoie de asigurări după efectuarea achiziției.','Email notifications' => 'Notificări prin e-mail','Enable thank you page and order details optimizations to see more options' => 'Activați optimizările pentru pagina de mulțumire și detaliile comenzii pentru a vedea mai multe opțiuni','Use wide layout on thank you page' => 'Folosiți un layout lat pe pagina de mulțumire','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Aceste opțiuni au efect asupra paginii de mulțumire, asupra afișării detaliilor comenzii pe paginile contului și asupra notificărilor prin e-mail.','Save settings' => 'Salvează setările','Docs' => 'Documente','Cart' => 'Coș de cumpărături','Thank you' => 'Mulțumesc','Address autocomplete' => 'Completarea automată a adresei','Trust badges' => 'Insigne de încredere','You do not have permission to save these settings.' => 'Nu aveți permisiunea de a salva aceste setări.','Invalid save request.' => 'Cerere de salvare nevalidă.','Your settings have been saved.' => 'Setările tale au fost salvate.','Saving...' => 'Se salvează...','Settings could not be saved. Please try again.' => 'Setările nu au putut fi salvate. Vă rugăm să încercați din nou.','Dismiss notice' => 'Ignorare notificare','Open settings menu' => 'Deschide meniul de setări','Close settings menu' => 'Închide meniul de setări','Preview' => 'Previzualizare','Expand preview' => 'Extinde previzualizarea','Collapse preview' => 'Ascunde previzualizarea','Show header and footer' => 'Afișează antetul și subsolul','Hide header and footer' => 'Ascunde antetul și subsolul','Page preview' => 'Previzualizare pagină','Preview viewport' => 'Fereastră de previzualizare','Tablet' => 'Tabletă','Desktop' => 'Desktop','Preview width' => 'Lățimea previzualizării','Decrease width' => 'Reducerea lățimii','Preview width in pixels' => 'Lățimea previzualizării în pixeli','Increase width' => 'Mărește lățimea','Preview as' => 'Previzualizare ca','Guest' => 'Oaspete','Logged in' => 'Autentificat','Preview page' => 'Pagina de previzualizare','Expand preview for a closer look' => 'Extindeți previzualizarea pentru a vedea mai în detaliu','Available with %s.' => 'Disponibil cu %s.','Turn them on' => 'Porniți-le','Optimizations for this page are turned off. %s to preview the page.' => 'Optimizările pentru această pagină sunt dezactivate. %s pentru a vizualiza pagina.','%s preview' => 'Previzualizare %s','Isolated session · nothing is saved' => 'Sesiune izolată · nu se salvează nimic','Usage tracking' => 'Urmărirea utilizării','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Trimiteți rapoarte privind mediul site-ului care nu conțin informații sensibile pentru a ajuta Fluid Checkout să-și îmbunătățească compatibilitatea. Rapoartele nu sunt trimise decât după ce această opțiune este activată în setările de mai jos.','Send usage tracking reports to Fluid Checkout' => 'Trimiteți rapoarte de monitorizare a utilizării către Fluid Checkout','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Aceste rapoarte ne ajută să îmbunătățim compatibilitatea și asistența pentru site-ul dumneavoastră și sunt trimise săptămânal, dacă această opțiune este activată.','No customer, admin user, or any other sensitive data is included in the reports.' => 'Rapoartele nu conțin date referitoare la clienți, utilizatori cu drepturi de administrator sau orice alte date sensibile.','Basic environment info' => 'Informații de bază despre mediu','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'Date referitoare la WordPress, PHP, WooCommerce, temă și pluginuri. Sunt incluse întotdeauna atunci când raportarea este activată. Ne ajută să înțelegem mediul în care rulează site-ul tău.','Plugin settings' => 'Setări plugin','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Trimite setările pluginului Fluid Checkout pentru a ne ajuta în soluționarea solicitărilor de asistență și pentru a ne ajuta să înțelegem modul în care utilizați pluginurile noastre.','Coming soon' => 'În curând','Sales metrics' => 'Indicatori de vânzări','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Numărul de comenzi lunare și vânzările totale din perioada de un an anterioară instalării Fluid Checkout și până în prezent. Aceste date ne ajută să înțelegem dacă obțineți venituri mai mari cu pluginurile noastre instalate. Nu se transmit niciodată date despre clienți sau utilizatori.','Utilities' => 'Servicii publice','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Folosiți componentele de meniu derulant <code>TomSelect</code> în locul celor <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect este o componentă de selecție cu meniu derulant mai simplă, care prezintă un risc mai mic de erori decât Select2, oferind totodată aceeași funcționalitate.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Setează dimensiunea fontului din câmpurile formularului la 16px pe paginile optimizate de acest plugin, pentru a evita mărirea automată a imaginii atunci când se interacționează cu câmpurile formularului pe dispozitive cu ecran mic.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Safari și alte browsere pot mări automat imaginea pe dispozitivele mobile pentru a facilita citirea textului atunci când dimensiunea fontului este mai mică de 16px.','Enable script processing tracking on the browser console.' => 'Activează urmărirea procesării scripturilor în consola browserului.','Unminified assets' => 'Resurse neminificate','Google Maps scripts' => 'Scripturi pentru Google Maps','Do not remove duplicate Google Maps scripts' => 'Nu ștergeți scripturile Google Maps care se repetă','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Când această opțiune este activată, scripturile Google Maps duplicate NU vor fi eliminate, ceea ce poate duce la erori și probleme de performanță. Utilizați această opțiune numai în timpul depanării.','Widget areas' => 'Zonele pentru widgeturi','Last step on mobile' => 'Ultimul pas pe dispozitivul mobil','Display widgets only at last step on mobile' => 'Afișează widgeturile doar la ultimul pas pe dispozitivele mobile','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Afișează widgeturile cu insigna de încredere pentru finalizarea comenzii numai atunci când se vizualizează ultimul pas al procesului de finalizare a comenzii pe dispozitivele mobile','Standard' => 'Standard','VAT number field' => 'Câmpul pentru numărul de TVA','Add a VAT number field to the billing form.' => 'Adăugați un câmp pentru numărul de TVA în formularul de facturare.','Field label' => 'Etichetă de câmp','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Setați eticheta câmpului pentru numărul de TVA (de exemplu, „Număr de TVA”). În cazul site-urilor web multilingve, este recomandat să lăsați acest câmp necompletat și să traduceți textul original.','VAT Number' => 'Număr de înregistrare TVA','EU-VAT' => 'TVA-UE','Enable the VAT number field to see more options' => 'Activează câmpul pentru numărul de TVA pentru a vedea mai multe opțiuni','VAT validation' => 'Validarea TVA-ului','Validate VAT number field for EU-VAT during checkout' => 'Validarea câmpului „Număr de TVA” pentru TVA-ul UE în timpul finalizării comenzii','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Verifică dacă numărul de TVA furnizat este un număr de TVA valabil, înregistrat în baza de date europeană VIES (Sistemul de schimb de informații privind TVA-ul).','Shop VAT number' => 'Numărul de TVA al magazinului','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'Numărul de TVA al magazinului, utilizat pentru solicitarea validării TVA-ului UE și tipărit pe facturi. <br><strong>Vă recomandăm cu tărie să adăugați numărul de TVA al magazinului dvs.</strong>, deoarece, în caz contrar, rezultatele consultării VIES ar putea să nu fie valabile în scopuri contabile. <br>De exemplu: <code>ATU99999999</code> sau <code>EE999999999</code>.','Reverse charge' => 'Autoliquidare','Apply reverse charge mechanism' => 'Aplicarea mecanismului de taxare inversă','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Setați cota de impozit la zero și afișați mențiunea „Reverse charge” pe facturi atunci când numărul de TVA al clientului este valabil. Este posibil să fie necesar un text diferit pentru „Reverse charge”, în funcție de țara în care se află magazinul.','Same country' => 'Aceeași țară','Apply reverse charge mechanism for transactions in the shop country:' => 'Aplicați mecanismul de taxare inversă pentru tranzacțiile efectuate în țara în care se află magazinul:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Permite aplicarea mecanismului de taxare inversă pentru tranzacțiile dintre companii din aceeași țară cu magazinul.','Reverse charge exceptions' => 'Excepții de la mecanismul de taxare inversă','Select additional countries to skip applying the reverse charge mechanism.' => 'Selectați țări suplimentare pentru a nu aplica mecanismul de taxare inversă.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Pentru comenzile din aceste țări se vor percepe taxe, chiar și în cazul în care se furnizează un număr de TVA valabil.','Reverse charge label on invoices' => 'Mențiunea privind inversarea obligației de plată pe facturi','Set the label of "reverse charge" on the checkout page and order details.' => 'Setați eticheta „taxare inversă” pe pagina de finalizare a comenzii și în detaliile comenzii.','Reverse charge text on invoices' => 'Textul privind mecanismul de taxare inversă pe facturi','Set the label of "reverse charge" text on invoices.' => 'Setați eticheta textului „taxare inversă” pe facturi.','Tax to be paid on reverse charge basis' => 'Impozitul se plătește pe baza mecanismului de taxare inversă','Company name' => 'Denumirea companiei','Autocomplete company name from VAT number' => 'Completarea automată a denumirii companiei pe baza numărului de TVA','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Completați denumirea societății de facturare pe baza numărului de TVA valabil furnizat de client.','Company name editing' => 'Modificarea denumirii companiei','Allow editing of auto-filled company name' => 'Permiteți editarea denumirii companiei completate automat','When enabled, customers can change the company name associated with the provided VAT number.' => 'Când această opțiune este activată, clienții pot modifica denumirea companiei asociată cu numărul de TVA furnizat.','EU-VAT for digital goods' => 'TVA-ul UE pentru bunurile digitale','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'Începând cu 1 ianuarie 2015, au fost aduse modificări la reglementările UE privind TVA-ul pentru bunurile digitale, care vizează exclusiv tranzacțiile B2C. TVA-ul pentru bunurile digitale trebuie calculat în funcție de locația clientului, iar dovezile în acest sens trebuie colectate (adresa IP și adresa de facturare).','Tax classes for digital goods' => 'Categorii fiscale pentru bunurile digitale','Select some tax classes' => 'Selectați câteva categorii fiscale','Location evidence' => 'Dovezi privind locația','Collect customer\'s location evidence' => 'Colectarea dovezilor privind locația clientului','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Salvează adresa IP și o verifică în raport cu adresa de facturare a clientului. Clienții trebuie să-și confirme adresa de facturare bifând o casetă de selectare pe pagina de finalizare a comenzii, în cazul în care țara din adresa de facturare și cea din adresa IP nu coincid.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Această opțiune se gestionează în Fluid Checkout. <a href="%s">Modificați-o din setările conturilor clienților</a>.','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Această opțiune se gestionează în Fluid Checkout. O puteți modifica din Fluid Checkout > Conturi clienți.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Această opțiune este gestionată în Fluid Checkout. Destinația de livrare este întotdeauna setată la „Implicit la adresa de livrare a clientului” atunci când Fluid Checkout este activat. Clienții pot totuși să furnizeze adrese de livrare și de facturare diferite în timpul finalizării comenzii.<br><br>O opțiune pentru setarea adresei de facturare implicite ca fiind aceeași cu adresa de livrare este disponibilă în <a href="%s">setările Fluid Checkout</a>.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Această opțiune este gestionată în Fluid Checkout. Destinația de livrare este întotdeauna setată la „Implicit la adresa de livrare a clientului” atunci când Fluid Checkout este activat. Clienții pot totuși să furnizeze adrese de livrare și de facturare diferite în timpul finalizării comenzii.<br><br>O opțiune pentru setarea adresei de facturare implicite ca fiind aceeași cu adresa de livrare este disponibilă în WooCommerce > Setări > Fluid Checkout.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Aceste setări au fost mutate în WP Admin > Fluid Checkout > Setări.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Această filă „Setări WooCommerce” este învechită și va fi eliminată în Fluid Checkout 6.0.','Go to settings page' => 'Accesează pagina de setări','Hide this tab permanently' => 'Ascunde definitiv această filă','Site report preview' => 'Previzualizare raport privind amplasamentul','This is the data that would be included in the next site environment report based on your current settings.' => 'Acestea sunt datele care ar fi incluse în următorul raport privind mediul site-ului, pe baza setărilor dvs. actuale.','Loading report preview...' => 'Se încarcă previzualizarea raportului...','Could not load the site report preview. Try again.' => 'Nu s-a putut încărca previzualizarea raportului site-ului. Încercați din nou.','Could not send the site report. Try again.' => 'Nu s-a putut trimite raportul privind site-ul. Încercați din nou.','Site report sent successfully.' => 'Raportul privind site-ul a fost trimis cu succes.','Enable and send now' => 'Activează și trimite acum','Close' => 'Închide','A site report request is already in progress. Try again in a moment.' => 'O solicitare de raport privind amplasamentul este deja în curs de procesare. Vă rugăm să încercați din nou peste câteva momente.','Site environment reporting is disabled.' => 'Raportarea privind mediul site-ului este dezactivată.','No site report data is available to send.' => 'Nu sunt disponibile date din rapoartele de șantier care să poată fi transmise.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Domeniul acestui site nu poate trimite rapoarte de mediu (domeniile locale sau de dezvoltare sunt excluse).','A site report was sent recently. Try again later.' => 'Recent a fost trimis un raport privind amplasamentul. Vă rugăm să încercați din nou mai târziu.','The site report could not be sent. Try again later.' => 'Nu s-a putut trimite raportul privind site-ul. Încercați din nou mai târziu.','Site environment reporting is not available.' => 'Raportarea privind mediul înconjurător al amplasamentului nu este disponibilă.','No site report data is available for the selected settings.' => 'Nu sunt disponibile date din rapoartele de amplasament pentru setările selectate.','You are not allowed to manage site reports.' => 'Nu aveți dreptul să gestionați rapoartele site-ului.','PRO feature' => 'Funcție PRO','Other plugins' => 'Alte pluginuri','Get only this add-on &mdash; %s' => 'Achiziționează doar acest supliment — %s','Install add-on' => 'Instalează extensia','Upgrade to PRO &mdash; %s' => 'Treci la versiunea PRO — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Achiziționează %2$s</a> pentru a debloca aceste opțiuni.','Add-on' => 'Componenta suplimentară','View documentation' => 'Vizualizați documentația','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Solicitările necesită un utilizator WordPress autentificat. Omiteți parametrul user_id pentru a utiliza datele utilizatorului curent sau specificați un user_id pentru a viza un alt cont, în cazul în care solicitantul are dreptul de a edita acel utilizator (dreptul edit_user). Solicitările neautentificate returnează fc_api_forbidden. Un user_id nevalid returnează fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 cu { "data": { ... } } atunci când handlerul returnează o încărcătură.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 cu { "success": true } atunci când nu există încărcătură (de exemplu, DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Eroile returnează un mesaj de eroare JSON REST WordPress provenit din WP_Error (cod, mesaj, data.status). Codurile Wire utilizează prefixul fc_api_*.','Forbidden access.' => 'Accesul interzis.','Target user was not found.' => 'Utilizatorul vizat nu a fost găsit.','This feature is not available.' => 'Această funcție nu este disponibilă.','A required address field is missing.' => 'Lipsește un câmp obligatoriu pentru adresă.','Postcode or ZIP is invalid.' => 'Codul poștal sau ZIP-ul nu este valid.','Phone number is invalid.' => 'Numărul de telefon nu este valid.','State or county is invalid.' => 'Statul sau județul nu este valid(ă).','Country is invalid or has no address fields.' => 'Țara nu este validă sau nu are câmpuri pentru adresă.','The request could not be processed.' => 'Solicitarea nu a putut fi procesată.','Back to previous step' => 'Înapoi la pasul anterior','Skip to settings' => 'Treci direct la setări','Start over and return to the first guided setup step' => 'Începeți din nou și reveniți la primul pas al configurării ghidate','Start over' => 'Începe din nou','Please complete all sub-steps before continuing.' => 'Vă rugăm să finalizați toate etapele intermediare înainte de a continua.','Expand' => 'Extindeți','Collapse' => 'Reduce','Skip' => 'Sari peste','Mark as complete' => 'Marchează ca finalizat','Mark as incomplete' => 'Marchează ca incompletă','View full-size image: %s' => 'Vizualizează imaginea la dimensiune maximă: %s','Full-size setup guide image' => 'Imagine cu ghidul de configurare la dimensiune maximă','Close image' => 'Închide imaginea','Fluid Checkout Guided Setup' => 'Configurare ghidată pentru Fluid Checkout','Welcome' => 'Bine ați venit','Explore your checkout' => 'Explorați procesul de finalizare a comenzii','All set' => 'Totul e gata','You do not have permission to access this page.' => 'Nu aveți permisiunea de a accesa această pagină.','Go to step %1$d: %2$s' => 'Mergi la pasul %1$d: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Acest ghid de configurare vă ajută să vă familiarizați cu Fluid Checkout. Pașii de mai jos sunt, deocamdată, doar orientativi.','Continue to the next step when you are ready.' => 'Când ești gata, treci la pasul următor.','Open your store checkout to see Fluid Checkout in action.' => 'Deschideți pagina de finalizare a comenzii din magazinul dvs. pentru a vedea cum funcționează Fluid Checkout.','View checkout page' => 'Afișează pagina de finalizare a comenzii','You can return to Fluid Checkout settings to continue configuring your store.' => 'Puteți reveni la setările Fluid Checkout pentru a continua configurarea magazinului dumneavoastră.','Review checkout and cart settings' => 'Verificați setările privind finalizarea comenzii și coșul de cumpărături','Explore add-ons from the dashboard' => 'Explorați extensiile din panoul de control','Finish & go to settings' => 'Finalizează și accesează setările','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Actualizați opțiunea de vizibilitate a câmpului „Număr de telefon pentru facturare” de la valoarea inițială, astfel încât să respecte convențiile WooCommerce.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Actualizați opțiunea de vizibilitate a câmpului „Număr de telefon pentru livrare” de la valoarea inițială, pentru a se conforma convențiilor WooCommerce.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Copiați setarea culorii de fundal din rezumatul comenzii în noua opțiune de culoare de fundal a coloanei secundare din designul „Split”.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Funcția de selectare avansată a câmpurilor este întotdeauna dezactivată atunci când se utilizează pluginul Biteship.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Poziția butonului de plasare a comenzii este întotdeauna setată la „Sub rezumatul comenzii” atunci când se utilizează pluginul German Market. Acest plugin impune ca butonul de plasare a comenzii și casetele de selectare privind aspectele legale să fie afișate sub rezumatul comenzii.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Poziția butonului de plasare a comenzii este întotdeauna setată la „Sub rezumatul comenzii” atunci când se utilizează Germanized pentru WooCommerce. Acest plugin impune ca butonul de plasare a comenzii și casetele de selectare privind informațiile legale să fie afișate sub rezumatul comenzii.','Edit pickup locations' => 'Editează locațiile de preluare','Use local pickup label from WooCommerce settings' => 'Utilizați eticheta de ridicare locală din setările WooCommerce','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Când este activată, eticheta opțiunii de ridicare de la casă corespunde titlului din setările WooCommerce privind locația de ridicare. Când este dezactivată, eticheta utilizează textul traducibil „Ridicare locală” din Fluid Checkout.','Button label for applying coupon codesApply' => 'Aplicați','Checkout step titleContact' => 'Persoană de contact','Checkout step titleShipping' => 'Transport maritim','Checkout step titleBilling' => 'Facturare','Checkout step titlePayment' => 'Plata','Checkout substep change link labelChange' => 'Schimbare','Checkout substep save link labelSave changes' => 'Salvați modificările','Substep review textNone.' => 'Niciuna.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Nu este selectată nicio imagine.','Settings sectionCart' => 'Cart','Settings sectionOrder pay' => 'Comanda de plată','Settings sectionThank you' => 'Vă mulțumim','Settings section titleIntegrations' => 'Integrări','Settings section titleLicense keys' => 'Chei de licență','Captcha positionBefore place order section' => 'Înainte de a plasa secțiunea de comandă','Captcha positionBefore place order button' => 'Înainte de a plasa butonul de comandă','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Închidere','Log in link label at checkout contact stepLog in' => 'Conectați-vă','Log in separator label at for when guest checkout is disabledOr continue below' => 'Sau continuați mai jos','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'Sau continuați ca invitat','Clear image selection on admin pages.Remove image' => 'Eliminați imaginea','shipping packagesShipping %d' => 'Transport %d','shipping packagesShipping' => 'Transport maritim','Used as fallback for "Proceed to next step" button labelnext step' => 'pasul următor','Substep review checkbox valueYes' => 'Da','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'John','Dummy customer last name in the admin previewDoe' => 'Căprioară','Dummy customer company in the admin previewExample Company' => 'Exemplu de companie','Dummy customer street address in the admin preview123 Main Street' => 'Strada Principală nr. 123','Dummy customer city in the admin previewAnytown' => 'Orașul Oarecare','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'Vă rugăm să lăsați coletul la ușa de la intrare.','Dummy product name in the admin previewBeanie' => 'Căciulă','Dummy product name in the admin previewCap' => 'Capac','Dummy product name in the admin previewT-Shirt' => 'Tricou','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'Am primit comanda dumneavoastră și vă vom trimite o notificare când va fi expediată.','Dummy download in the admin previewUser guide' => 'Ghidul utilizatorului','Google Places API versionsPlaces API (New)' => 'API-ul Locuri (Nou)','Google Places API versionsPlaces API (Legacy)' => 'API-ul Locuri (versiune veche)','Brasil API versionsVersion 1' => 'Versiunea 1','Brasil API versionsVersion 2' => 'Versiunea 2','Delayed account creation benefits placeholder text✔ Checkout faster next time
