✔ Vezi starea și istoricul comenzilor','VAT number field visibilityHidden' => 'Ascuns','VAT number field visibilityOptional' => 'Opțional','VAT number field visibilityRequired' => 'Obligatoriu','Delivery typeShipping to address' => 'Adresa de livrare','Delivery typeLocal pickup' => 'Ridicare de la sediu',] ];